#!/usr/bin/env python3
"""One-time Online Subscriptions import script. Run on Render Shell."""
import os, json, gzip, base64, psycopg2, psycopg2.extras
from datetime import datetime

DATA = """"""

def main():
    rows = json.loads(gzip.decompress(base64.b64decode(DATA)))
    conn = psycopg2.connect(os.environ["DATABASE_URL"], cursor_factory=psycopg2.extras.RealDictCursor)
    cur = conn.cursor()
    imported = updated = skipped = 0
    for row in rows:
        candidate = row.get("Candidate Name", "").strip() or row.get("Enter Candidate Name", "").strip()
        if not candidate:
            skipped += 1
            continue
        parts = candidate.rsplit(" - ", 1)
        reg_num = parts[1].strip() if len(parts) == 2 else ""
        if not reg_num:
            skipped += 1
            continue
        cur.execute("SELECT registration_number FROM plab_clients WHERE registration_number = %s", (reg_num,))
        if not cur.fetchone():
            skipped += 1
            continue
        g = lambda k: row.get(k, "").strip()
        def parse_date(v):
            v = v.strip() if v else ""
            if not v:
                return ""
            for fmt in ("%Y-%m-%d", "%d-%b-%Y", "%d/%m/%Y", "%Y-%m-%d %H:%M:%S"):
                try:
                    return datetime.strptime(v, fmt).strftime("%Y-%m-%d")
                except ValueError:
                    continue
            return v
        subscription = g("Online Subscription")
        issued_date = parse_date(g("Issued Date"))
        activation = g("Activation type") or g("Activation Type")
        notes = g("Notes")
        client_email = g("Client Email")
        login_id = g("Login Id")
        password = g("Password")
        booked_by = g("Booked By")
        mobile = g("Mobile Number")
        candidate_email = g("Candidate Email")

        cur.execute(
            "SELECT id FROM ops_online_subscriptions WHERE registration_number = %s AND COALESCE(online_subscription,'') = %s AND COALESCE(issued_date,'') = %s",
            (reg_num, subscription, issued_date)
        )
        exists = cur.fetchone()
        if exists:
            cur.execute("""UPDATE ops_online_subscriptions SET
                activation_type=%s, notes=%s, client_email=%s,
                login_id=%s, password=%s, booked_by=%s,
                mobile_number=%s, candidate_email=%s WHERE id=%s""", (
                activation, notes, client_email,
                login_id, password, booked_by,
                mobile, candidate_email, exists["id"]
            ))
            updated += 1
        else:
            cur.execute("""INSERT INTO ops_online_subscriptions (
                registration_number, online_subscription, issued_date, activation_type,
                notes, client_email, login_id, password, booked_by,
                mobile_number, candidate_email, created_by
            ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", (
                reg_num, subscription, issued_date, activation,
                notes, client_email, login_id, password, booked_by,
                mobile, candidate_email, 0
            ))
            imported += 1
    conn.commit()
    cur.close()
    conn.close()
    print(f"Subscriptions: {imported} new, {updated} updated, {skipped} skipped")
    print(f"Total Subscriptions: {imported + updated + skipped}")

if __name__ == "__main__":
    main()
